# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞA VE KÜLTÜR AYRIMI İLE KÜLTÜR FELSEFESİNİN PROBLEMLERİ</text>\n  <rect x="25" y="48" width="310" height="182" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Doğa – Kültür Karşılaştırması</text>\n  <text x="40" y="98" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">Doğa (Tabiat):</tspan> İnsan dışında kendiliğinden</text>\n  <text x="48" y="113" font-size="10" fill="#475569">var olan, determinist yasalara tabi alandır.</text>\n  <text x="40" y="138" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">Kültür (Ekin):</tspan> İnsanın doğayı dönüştürerek</text>\n  <text x="48" y="153" font-size="10" fill="#475569">ürettiği maddi-manevi değerler ve anlam dünyasıdır.</text>\n  <rect x="42" y="168" width="276" height="46" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="186" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Ernst Cassirer\'in İnsan Tanımı:</text>\n  <text x="180" y="203" text-anchor="middle" font-size="10" fill="#334155">\'İnsan; dil, sanat ve değer üreten simgesel varlıktır.\'</text>\n\n  <rect x="365" y="48" width="310" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. Kültür Felsefesinin Temel Soruları</text>\n  <text x="380" y="98" font-size="10.5" fill="#334155">• Kültür evrensel midir, toplumlara göre göreli midir?</text>\n  <text x="380" y="120" font-size="10.5" fill="#334155">• Küreselleşme kültürel çeşitliliği yok eder mi?</text>\n  <text x="380" y="142" font-size="10.5" fill="#334155">• Etnosantrizm (kültür merkezciliği) nasıl aşılır?</text>\n  <text x="380" y="164" font-size="10.5" fill="#334155">• Çok kültürlü toplumda birlikte yaşama imkânı nedir?</text>\n  <rect x="382" y="176" width="276" height="40" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="200" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Hedef: Yerel kimliği koruyarak evrensel barışa katkı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ESTETİK İLE SANAT FELSEFESİNİN KAPSAMI VE TEMEL KAVRAMLARI</text>\n  <rect x="20" y="45" width="310" height="195" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="175" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">ESTETİK (Geniş Kapsam: Doğa + Sanat)</text>\n  <text x="175" y="88" text-anchor="middle" font-size="10.5" fill="#4c1d95">Hem doğal güzelliği (gün batımı, şelale) hem de</text>\n  <text x="175" y="103" text-anchor="middle" font-size="10.5" fill="#4c1d95">sanatsal güzelliği bütüncül olarak inceler.</text>\n  <rect x="40" y="118" width="270" height="106" rx="8" fill="#ffffff" stroke="#8b5cf6" stroke-width="2"/>\n  <text x="175" y="140" text-anchor="middle" font-size="12" font-weight="bold" fill="#6d28d9">SANAT FELSEFESİ (Dar Kapsam)</text>\n  <text x="175" y="160" text-anchor="middle" font-size="10" fill="#334155">• Yalnızca insanın ürettiği sanat eserini,</text>\n  <text x="175" y="176" text-anchor="middle" font-size="10" fill="#334155">sanatsal yaratmayı ve beğeniyi sorgular.</text>\n  <text x="175" y="196" text-anchor="middle" font-size="10" font-weight="bold" fill="#5b21b6">Not: Her sanat felsefesi sorusu estetiktir;</text>\n  <text x="175" y="211" text-anchor="middle" font-size="10" font-weight="bold" fill="#5b21b6">fakat estetik doğadaki güzeli de kapsar.</text>\n\n  <rect x="350" y="45" width="330" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Estetik Deneyimin Temel Kavramları</text>\n  <text x="365" y="94" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Estetik Özne:</tspan> Güzelliği algılayan ve haz duyan insan.</text>\n  <text x="365" y="116" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Estetik Nesne:</tspan> Estetik yönelim konusu olan eser/doğa.</text>\n  <text x="365" y="138" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Estetik Tavır:</tspan> Çıkar ve fayda gözetmeyen saf seyir.</text>\n  <text x="365" y="160" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Estetik Yargı:</tspan> \'Bu tablo güzeldir\' beğeni hükmü.</text>\n  <text x="365" y="182" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Yüce (Sublim):</tspan> İnsanı aşan, hayranlık ve ürperti</text>\n  <text x="373" y="197" font-size="10" fill="#475569">veren devasa büyüklük (fırtınalı okyanus, dağlar).</text>\n  <text x="365" y="218" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Hoş:</tspan> Duyulara anlık ve yüzeysel haz veren şey.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SANAT FELSEFESİNDE SANATI AÇIKLAYAN ÜÇ TEMEL KURAM</text>\n  <rect x="20" y="48" width="210" height="188" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0369a1">1. Taklit (Mimesis) Kuramı</text>\n  <text x="125" y="90" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0c4a6e">(Platon &amp; Aristoteles)</text>\n  <text x="32" y="114" font-size="10" fill="#334155">• Sanat doğanın taklit edilmesidir</text>\n  <text x="40" y="128" font-size="10" fill="#334155">(doğaya tutulan ayna).</text>\n  <text x="32" y="150" font-size="10" fill="#334155">• <tspan font-weight="bold">Platon:</tspan> İdeaların kopyasının</text>\n  <text x="40" y="164" font-size="10" fill="#334155">kopyasıdır, yanıltıcıdır.</text>\n  <text x="32" y="186" font-size="10" fill="#334155">• <tspan font-weight="bold">Aristoteles:</tspan> Olanı değil olması</text>\n  <text x="40" y="200" font-size="10" fill="#334155">gerekeni yansıtır; katharsis sağlar.</text>\n\n  <rect x="245" y="48" width="210" height="188" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Yaratma Olarak Sanat</text>\n  <text x="350" y="90" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">(Benedetto Croce)</text>\n  <text x="257" y="114" font-size="10" fill="#334155">• Sanatçı doğayı kopyalamaz;</text>\n  <text x="265" y="128" font-size="10" fill="#334155">hayal gücüyle olmayanı üretir.</text>\n  <text x="257" y="150" font-size="10" fill="#334155">• Sanat, sanatçının öznel duygu</text>\n  <text x="265" y="164" font-size="10" fill="#334155">ve sezgilerinin dışa vurumudur.</text>\n  <text x="257" y="186" font-size="10" fill="#334155">• Sanat eseri tamamen özgün,</text>\n  <text x="265" y="200" font-size="10" fill="#334155">biricik ve tekrarsızdır.</text>\n\n  <rect x="470" y="48" width="210" height="188" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Oyun Olarak Sanat</text>\n  <text x="575" y="90" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">(Friedrich Schiller)</text>\n  <text x="482" y="114" font-size="10" fill="#334155">• Sanat da oyun gibi fayda ve</text>\n  <text x="490" y="128" font-size="10" fill="#334155">çıkar kaygısından bağımsızdır.</text>\n  <text x="482" y="150" font-size="10" fill="#334155">• Kurmaca bir evrende insanı</text>\n  <text x="490" y="164" font-size="10" fill="#334155">zamanın baskısından kurtarır.</text>\n  <text x="482" y="186" font-size="10" font-weight="bold" fill="#166534">• \'İnsan oynadığı sürece</text>\n  <text x="490" y="200" font-size="10" font-weight="bold" fill="#166534">gerçek anlamda özgürdür.\'</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
